[93904] = {id=93904,name="Defying Gravity",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16648,mapID=2527,description="Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you. Kalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain. But we must proceed and claim the power within. Fill the reliquary to the brim. I know not what to expect from my voidwalker. We will need all the power we can manage.",questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Void Power Collected"},{orderIndex=4,type=0,amount=1,objectID=245756,text="Activate the Gravity Anomaly to travel up"}},worldTaskTitle="Defying Gravity",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93905] = {id=93905,name="Ongoing Stoppage",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15458,mapID=2405,description="The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped. Put down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.",questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Manaforge Disrupted"},{orderIndex=1,type=2,amount=10,objectID=509568,text="Manaturret Destroyed"}},worldTaskTitle="Ongoing Stoppage",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
