[96633] = {id=96633,name="Equipment Seminar",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Welcome back, ! I've continued my collaboration with the artisans here in Silvermoon. Their techniques have only grown more refined. Infusing equipment with the essence of the dawn is no longer just theory, it's becoming an art form. I'm eager to resume our work together. Bring me another piece of Adventurer equipment, and we'll see how these improved methods hold up in practice. Plenty of people are always in need of a capable hand. Help them, and they'll reward you accordingly.",starts={{npcID=239676,x=0.486,y=0.618,mapID=2393}},ends={{npcID=239676,x=0.486,y=0.618,mapID=2393}},coords={x=0.486,y=0.618,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Equipment Seminar",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[96635] = {id=96635,name="Upgrade Practicum",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Cuzolth and I have pushed our craft further than ever, allowing us to imbue your gear with greater power. To unlock its full potential, we'll need Mistcrests. They're drawn from trials of all kinds--greater dangers yield stronger crests, though even Adventurer Mistcrests carry a spark of that power. Bring me fifty Adventurer Mistcrests, . Let's see what your equipment is truly capable of.",starts={{npcID=239676,x=0.486,y=0.618,mapID=2393}},ends={{npcID=239676,x=0.486,y=0.618,mapID=2393}},coords={x=0.486,y=0.618,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Upgrade Practicum",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[96637] = {id=96637,name="Veteran Symposium",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="There is a lot more power where that came from! Upgrades scale with strength. Higher quality items can reach higher heights of power. For this step, I'll need Veteran equipment along with some Veteran Mistcrests. Once you bring them, Cuzolth and I can continue making the enhancements.",starts={{npcID=239676,x=0.486,y=0.618,mapID=2393}},ends={{npcID=239676,x=0.486,y=0.618,mapID=2393}},coords={x=0.486,y=0.618,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Veteran Symposium",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[96639] = {id=96639,name="Patrolling the Temple",expansion=11,mapID=2509,questType="world",worldTaskTitle="Patrolling the Temple",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96640] = {id=96640,name="Bounty of the Cursed",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="Dis temple holds many secrets, $p. Ancient power, just waitin' for someone to take it. De Soulcoilers might be dead, but their power remains. Find their caches and bring me whatever you find.",starts={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},ends={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},coords={x=0.51,y=0.626,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Bounty of the Cursed",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96641] = {id=96641,name="Relentless Strikes",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="Some say de forces of Ula'tek are endless--dat we can never kill them all. But I like a challenge. How 'bout you? Strike de enemy hard, and we'll see how endless dey are.",starts={{npcID=272109,x=0.478,y=0.65,zoneID=16535}},ends={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},coords={x=0.478,y=0.65,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Relentless Strikes",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96642] = {id=96642,name="Decisive Incursions",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="De strikes are de first step. We cannot let de enemy recover. First we batter them, soften 'em up. Then, we hit dem hard and fast with everything we've got. We don't have de forces for a longer battle. When de time comes for de incursion, you'd best be ready. Gather your allies. De enemy is mighty.",starts={{npcID=272109,x=0.478,y=0.65,zoneID=16535}},ends={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},coords={x=0.478,y=0.65,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Decisive Incursions",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96643] = {id=96643,name="From Whence it Came",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="Can you feel it? Old things lurk in de temple, just waitin' to rise once again. Dey are drawn by the sounds of battle, eager to visit their violence upon you. Find one of these ancient foes and ensure it does not rise again.",starts={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},ends={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},coords={x=0.51,y=0.626,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="From Whence it Came",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96644] = {id=96644,name="Essence of Malice",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="I'm in need of venom, pure and potent. De venom dat wells up through de ground is too diluted--fouled with other things. You need to find a font of de profane stuff. Search de depths of de vaults. Dat's where de true venom will be found.",starts={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},ends={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},coords={x=0.51,y=0.626,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Essence of Malice",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96649] = {id=96649,name="Mistcrest Capstone",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Crests aren't fixed in form, you can transmute them between tiers. If you're holding crests beyond what your current gear can use, I can refine them into lower tiers. And once your equipment advances, we can reverse the process and elevate lesser crests into greater ones. Let's start with a simple exercise. Bring me those Veteran Mistcrests, and I'll convert them into Adventurer Mistcrests.",starts={{npcID=239676,x=0.486,y=0.618,mapID=2393}},ends={{npcID=239676,x=0.486,y=0.618,mapID=2393}},coords={x=0.486,y=0.618,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Mistcrest Capstone",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
