[96725] = {id=96725,name="Sparks of War: Val",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The mysterious world of Val has been made accessible to us with a host of new creatures present. Go and see what you can find out about them.",starts={{npcID=254971,x=0.362,y=0.81,mapID=2393}},ends={{npcID=254971,x=0.362,y=0.81,mapID=2393}},coords={x=0.362,y=0.81,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Sparks of War: Val"},
[96726] = {id=96726,name="Sparks of War: Naigtal",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The mysterious world of Naigtal has been made accessible to us with a host of new creatures present. Go and see what you can find out about this world and what the ethereals are up to.",starts={{npcID=254971,x=0.362,y=0.81,mapID=2393}},ends={{npcID=254971,x=0.362,y=0.81,mapID=2393}},coords={x=0.362,y=0.81,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Sparks of War: Naigtal"},
[96746] = {id=96746,name="Sporefall: Rotmire",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Need help! End of Harandar! End of world! Spore Storm making something new for Grudge Pit, but too much. Too much! Can't control. Will break free! Destroy pit. Destroy us all! Must go to Sporefall, destroy Rotmire before they lose control! For Harandar! For Azeroth! For Grudge Pit!",starts={{npcID=266165,x=0.366,y=0.688,mapID=2393}},ends={{npcID=266165,x=0.366,y=0.688,mapID=2393}},coords={x=0.366,y=0.688,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Sporefall: Rotmire",db2QuestInfoID=62,db2QuestInfoName="Raid"},
[96808] = {id=96808,name="Sparks of War: The Coiled Isle",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="There's unknown danger out in the Coiled Isle . Get out there and clear things up!",starts={{npcID=254971,x=0.362,y=0.81,mapID=2393}},ends={{npcID=254971,x=0.362,y=0.81,mapID=2393}},coords={x=0.362,y=0.81,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Sparks of War: The Coiled Isle"},
[96809] = {id=96809,name="Exterior Manaforge Translocator",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,mapID=2600,description="Maneuvering through this spore-infested rock is quickly becoming a chore, I'm sure you would agree. Thankfully, I've figured out a way to make use of the existing Manaforge Translocator network that was so thoughtfully built prior to our arrival. I can show you how to \"activate\" them for our use. You can start with the one we... translocated to camp.",starts={{npcID=265559,x=0.478,y=0.812,zoneID=16943}},ends={{npcID=265559,x=0.478,y=0.812,zoneID=16943}},coords={x=0.478,y=0.812,source="quest_giver",zoneID=16943},questType="world",worldTaskTitle="Exterior Manaforge Translocator"},
