[96995] = {id=96995,name="Turn Back the Surge",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="De temple can no longer contain Ula'tek's wrath. De boldest of her brood are spilling out all over de isle! They'll destroy us all if we don't stem de tide of venom. Fight dem wherever dey dare to show their ugly heads. Do not let dem get a foothold.",starts={{npcID=267635,x=0.586,y=0.458,zoneID=16365}},ends={{npcID=267635,x=0.586,y=0.458,zoneID=16365}},coords={x=0.586,y=0.458,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Turn Back the Surge",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
