[98419] = {id=98419,name="Shoulder to Shoulder",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="De Vaults are a dangerous place. Lotta brave, headstrong fighters think dey can face de Children of Ula'tek alone. If dey're lucky, we manage to recover de bodies before dey get eaten. I like you, $p. It'd be a shame to see a serpent feed you to its young. So be smart. Find people to watch your back, then carve your way through de temple together.",starts={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},ends={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Shoulder to Shoulder",db2QuestInfoID=1,db2QuestInfoName="Group"},
[98420] = {id=98420,name="What's Out There?",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="Knowledge is de most important weapon in war. These Vaults are ancient and vast--our scouts cannot see everything. What lurks in de depths of these corrupted halls? Dat's precisely what I need to know. Get out there and tell me what you see, but it's dangerous to go alone. You best bring some comrades if you want to make it back.",starts={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},ends={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="What's Out There?",db2QuestInfoID=1,db2QuestInfoName="Group"},
}
end)
